function prepareOperationsExport({ service, url, spreadsheetId, range, eventType }) {
  if (eventType != null && eventType !== 'generate') throw new Error('This component handles only generate requests.');
  if (typeof service !== 'string' || !service.trim()) throw new Error('Supply the exact service name used in the operations sheet.');
  if (typeof url !== 'string' || !url.trim()) throw new Error('Supply the service documentation URL.');
  if (typeof spreadsheetId !== 'string' || !/^[A-Za-z0-9_-]+$/.test(spreadsheetId) || /YOUR_SPREADSHEET_ID/.test(spreadsheetId)) throw new Error('Configure your operations spreadsheet ID.');
  if (typeof range !== 'string' || !/^'(?:[^'\u0000-\u001f\u007f]|'')+'$/.test(range)) throw new Error('Configure the complete operations tab as a single-quoted A1 sheet name.');
  return { service, url, spreadsheetId, range, createdAt: new Date().toISOString() };
}

return $input.all().map((item,index)=>({json:prepareOperationsExport({...item.json,...(item.json.data??{}),spreadsheetId:item.json.spreadsheetId,range:item.json.range}),pairedItem:{item:index}}));

function sheetTable({ values, majorDimension = "ROWS" }) {
  if (majorDimension !== "ROWS" || !Array.isArray(values) || values.some((row) => !Array.isArray(row)))
    throw Error("Google Sheets must return row-oriented cell values.");
  const isEmpty = (value) => value == null || value === "", nonempty = (row) => row.some((value) => !isEmpty(value)), headerIndex = values.findIndex(nonempty);
  if (headerIndex < 0)
    return { columns: [], records: [] };
  const headers = values[headerIndex];
  if (headers.some((name) => typeof name !== "string" || !name.trim() || name === "row_number") || new Set(headers).size !== headers.length)
    throw Error("Use unique nonempty text headers; row_number is reserved.");
  const columns = ["row_number", ...headers], records = [];
  for (let index = headerIndex + 1;index < values.length; index++) {
    const cells = values[index];
    if (!nonempty(cells))
      continue;
    if (cells.slice(headers.length).some((value) => !isEmpty(value)))
      throw Error("Every populated column needs a header.");
    records.push(Object.fromEntries([["row_number", index + 1], ...headers.map((name, column) => [name, cells[column] ?? ""])]));
  }
  return { columns, records };
}

function buildOperationsExport({ values, majorDimension, service, url, createdAt }) {
  const table = sheetTable({ values, majorDimension });
  const required = ['service', 'resource', 'operation', 'description', 'url', 'method'];
  if (table.columns.length && required.some(name => !table.columns.includes(name))) throw new Error('The operations tab needs service, resource, operation, description, url and method columns.');
  const groups = new Map();
  let operationCount = 0;
  for (const row of table.records) {
    if (String(row.service) !== service) continue;
    for (const key of ['resource', 'operation', 'url', 'method']) if (typeof row[key] !== 'string' || !row[key].trim()) throw new Error('Each matching operation needs resource, operation, url and method text.');
    if (typeof row.description !== 'string') throw new Error('Operation descriptions must be text.');
    if (row.documentation_url != null && typeof row.documentation_url !== 'string') throw new Error('Method documentation URLs must be text when supplied.');
    const resource = row.resource.toLowerCase().trim().replace(/\bapi\b/g, '').replace(/\s+/g, ' ').trim();
    if (!resource) continue;
    if (!groups.has(resource)) groups.set(resource, { resource: resource[0].toUpperCase() + resource.slice(1), operations: [] });
    const description = row.description.trim(), period = description.indexOf('.');
    const operation = row.operation.trim();
    groups.get(resource).operations.push({ operation: operation[0].toUpperCase() + operation.slice(1), description: period > 0 ? description.slice(0, period + 1) : description, ApiUrl: row.url, method: row.method.trim().toUpperCase(), method_documentation_url: row.documentation_url || '' });
    operationCount++;
  }
  if (typeof createdAt !== 'string' || Number.isNaN(Date.parse(createdAt))) throw new Error('The export needs its run-start timestamp.');
  const timestamp = new Date(createdAt).toISOString().slice(0, 19).replace(/[-:]/g, '').replace('T', '_') + 'Z';
  const prefix = service.replace(/[^\p{L}\p{N}_-]+/gu, '_').replace(/^_+|_+$/g, '').toLowerCase() || 'service';
  const filename = prefix + '_api_operations_' + timestamp + '.json';
  const text = JSON.stringify({ documentation_url: url, endpoints: [...groups.values()] }, null, 4);
  if (new TextEncoder().encode(text).byteLength > 5000000) throw new Error('The generated JSON text exceeds the 5,000,000-byte content budget.');
  return { hasOperations: operationCount > 0, operationCount, filename, text };
}

return $input.all().map((item,index)=>({json:buildOperationsExport({...$("Prepare Export Request").itemMatching(index).json,values:item.json.values??[],majorDimension:item.json.majorDimension??"ROWS"}),pairedItem:{item:index}}));

function operationsExportReply({ exported, id, filename }) {
  if (!exported) return { exported: false, response: { id: null, filename: null } };
  if (typeof id !== 'string' || !id.trim() || typeof filename !== 'string' || !filename.trim()) throw new Error('Google Drive did not acknowledge the created export file.');
  return { exported: true, response: { id, filename } };
}

return $input.all().map((item,index)=>({json:operationsExportReply({exported:true,id:item.json.id,filename:$("Build Operations Export").itemMatching(index).json.filename}),pairedItem:{item:index}}));

function operationsExportReply({ exported, id, filename }) {
  if (!exported) return { exported: false, response: { id: null, filename: null } };
  if (typeof id !== 'string' || !id.trim() || typeof filename !== 'string' || !filename.trim()) throw new Error('Google Drive did not acknowledge the created export file.');
  return { exported: true, response: { id, filename } };
}

return $input.all().map((item,index)=>({json:operationsExportReply({exported:false}),pairedItem:{item:index}}));
